head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[selectbox > P > valueNotInList]<br/>아이템 리스트에 없는 아이템을 선택했을때 처리하는 방식을 설정합니다.",
    "validation" : [        
        "valueNotInList=keepValue 일때 실존하는 다른 아이템을 선택하면 설정되있던 임시 아이템은 완전히 사라집니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {                
        emptyItem : true,
        valueNotInList : "keepValue",
    }

    let cList = $c.gcm.createCList(properties)

    // target 생성    
    $c.gcm.createBasicSelectBox(cList);
}



scwin.btn_setValue_onclick = function (e) {
	target1.setValue(100);
    scwin.btn_getInfo_onclick();
};



scwin.btn_setSelectedIndex_onclick = function (e) {
	target1.setSelectedIndex(100);
    scwin.btn_getInfo_onclick();
};



scwin.btn_setText_onclick = function (e) {
	target1.setText("invalid");
    scwin.btn_getInfo_onclick();	
};



scwin.btn_getInfo_onclick = function (e) {
    let rtn = '';

    rtn = target1.getText();
	wf_body_bottom.getObj("scwin").setReturnValue("getText : " + rtn);

    rtn = target1.getValue();
	wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);    

    rtn = target1.getSelectedIndex();
	wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex : " + rtn);
};



scwin.btn_getItemList_onclick = function (e) {
    let rtn = '';    
    let comp = "target1_itemTable";
    let targetElements = document.querySelectorAll('[id*='+comp+']');

    if (targetElements.length == 0)
            wf_body_bottom.getObj("scwin").setReturnValue("SelectBox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    rtn = targetElements[0].textContent
    wf_body_bottom.getObj("scwin").setReturnValue("Itemlist label : " + rtn);
};
